import type { Metadata } from "next";

export const siteConfig = {
  name: "Surhires",
  // Set NEXT_PUBLIC_SITE_URL in Vercel once the production domain is known.
  url: process.env.NEXT_PUBLIC_SITE_URL ?? "https://surhires.vercel.app",
  description:
    "Surhires matches Indian employers with candidates on skills, location and pay. Post a job and get a ranked shortlist in days, or find roles with real salaries.",
};

/** Generated by app/opengraph-image.tsx. */
const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Surhires – hire faster, find work that pays fairly",
};

type PageMetadataInput = {
  title: string;
  description: string;
  path: string;
};

/**
 * Per-page metadata with a canonical URL and matching Open Graph/Twitter tags.
 * Metadata merges shallowly, so each page repeats the full openGraph object
 * (including the share image, which would otherwise be dropped).
 */
export function pageMetadata({ title, description, path }: PageMetadataInput): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: siteConfig.name,
      locale: "en_IN",
      url: path,
      title: `${title} | ${siteConfig.name}`,
      description,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: `${title} | ${siteConfig.name}`,
      description,
      images: [shareImage],
    },
  };
}
